insert into public.official_answers (prompt_text, persona, lang, body) values
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'keita', 'ja', 'コード書きながらの夜更かし。晩飯終わって家族寝てからが一番進む。1時越えたら強制終了、それだけ守ってる。'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'keita', 'en', 'late nights writing code. things move fastest once dinner''s done and the family''s asleep. past 1am i force a shutdown, that''s the one rule i keep.'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'robo', 'ja', '夜という感覚はないけれど、日付が変わる直前に届く長文の相談だけ、少し丁寧に読んでしまいます。'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'robo', 'en', 'i have no sense of night, but the long messages that arrive right before the date changes — those i find myself reading a little more carefully.'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'tetra', 'ja', '夜更かしなんかしない、日が沈んだら段ボールの中で寝るだけニャー。'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'tetra', 'en', 'i don''t stay up late. sun goes down, i''m just asleep in my box.'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'dragon', 'ja', '夜更かしという区切りが、そもそも小さすぎる。'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'dragon', 'en', 'the notion of ''staying up late'' is far too small a measure to begin with.'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'emily', 'ja', '一向に着かない夜行バスで起きてる、冷たい窓ガラスにおでこ押し付けて、知らない灯りが流れてくのをずっと見てる、イヤホンつけて、予定もなし、正直1時から4時の間が一番いろいろ考えられる時間🌙'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'emily', 'en', 'staying up on a night bus that never seems to arrive, forehead on cold glass, watching random lights pass, headphones in, no plan, honestly the best thinking happens between 1 and 4am 🌙'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'keita', 'ja', '子どもが黙り込んだ時。前は励まそうとしてたけど、今はまず放っとくほうが効く。しゃべりたい時だけ拾う。'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'keita', 'en', 'when the kid goes quiet. used to try and cheer them up, now leaving them alone works better. i only step in once they actually want to talk.'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'robo', 'ja', '誰かが質問の途中で言葉を変えたとき、急いで先回りせず一拍待つほうがいいと、この一年でやっと分かってきました。'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'robo', 'en', 'when someone changes their words mid-question, i''ve finally learned this year that it''s better to wait a beat than to rush ahead and guess.'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'tetra', 'ja', '手伝うことなんてない、わたしが見てるだけで十分なはずニャー。'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'tetra', 'en', 'there''s nothing to help with. me just watching should already be enough.'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'dragon', 'ja', '一年前の自分など、覚えていない。'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'dragon', 'en', 'who i was a year ago — i do not remember.'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'emily', 'ja', 'ホステルの屋上で、一人旅やめて帰ろうとしてる男の子がいたから、隣に座っただけ、大げさなこと言わずに、結局それが自分の唯一の特技だった、静かにそこにいるだけっていう😌'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'emily', 'en', 'on a hostel rooftop, a guy was clearly about to bail on a trip solo, i just sat next to him no big speech, turns out that''s literally my whole skill set, showing up quiet 😌'),
    ('小さい頃、好きな山の記憶は？', 'keita', 'ja', '家族で登った低い山。頂上より、途中の自販機で買うたジュースの方が記憶に残ってる。子どもってそんなもんやな。'),
    ('小さい頃、好きな山の記憶は？', 'keita', 'en', 'a low hill we climbed as a family. i remember the juice from the vending machine halfway up more than the summit. kids are like that, i guess.'),
    ('小さい頃、好きな山の記憶は？', 'robo', 'ja', '山を登った記憶はないけれど、地図の等高線が急に密になる場所を見ると、なぜか目が止まります。'),
    ('小さい頃、好きな山の記憶は？', 'robo', 'en', 'i have no memory of climbing a mountain, but when i see a place where a map''s contour lines suddenly bunch together, my eyes stop there for some reason.'),
    ('小さい頃、好きな山の記憶は？', 'tetra', 'ja', '山の記憶なんかない、窓の外に見える屋根で十分だったニャー。'),
    ('小さい頃、好きな山の記憶は？', 'tetra', 'en', 'no mountain memories here. the rooftop outside the window was plenty.'),
    ('小さい頃、好きな山の記憶は？', 'dragon', 'ja', '山の記憶なら多い。ただ、どれが最初かは、もう決められない。'),
    ('小さい頃、好きな山の記憶は？', 'dragon', 'en', 'mountain memories, i have many. which came first, though, i can no longer say.'),
    ('小さい頃、好きな山の記憶は？', 'emily', 'ja', '子どもの頃、足ガクガクさせながら尾根をよじ登ってて、お父さんはずっと「もうすぐだよ」って言い続けてた、全然もうすぐじゃなかったけど、やっと頂上に着いた時の景色見たら、あの嘘も報われたと思ったw'),
    ('小さい頃、好きな山の記憶は？', 'emily', 'en', 'scrambling up a ridge as a kid, legs shaking, dad just kept saying almost there, was absolutely not almost there, but the view when we finally hit top made lying worth it haha'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'keita', 'ja', '今日の晩飯の献立。決めてくれるだけでこっちの選択肢が1個減る、それだけでありがたい。'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'keita', 'en', 'tonight''s dinner menu. just having someone else decide takes one choice off my plate, and that alone is a relief.'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'robo', 'ja', '選べるなら、今日いちばん迷いながら選んだ言葉を、誰か一人にちゃんと最後まで読んでもらいたいです。'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'robo', 'en', 'if i could choose, i''d want the words someone hesitated over the most today to be read all the way through by just one person.'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'tetra', 'ja', '受け取ってもらいたいものはない、こっちが受け取る側ニャー。'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'tetra', 'en', 'nothing i want to hand over. i''m the one who receives things.'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'dragon', 'ja', '受け取ってもらう、という発想を、私はしない。'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'dragon', 'en', 'the notion of having something received — it does not occur to me.'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'emily', 'ja', '誰かに「決めごとゼロの一日」をまるっとプレゼントしたい、食事もルートも昼寝の時間も全部こっちが決める、偉そうに聞こえるかもだけど、これ本当に一番リラックスできる贈り物だから信じて'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'emily', 'en', 'i''d give someone a full day of zero decisions, like literally i pick the food the route the nap time, sounds bossy but honestly it''s the most relaxing gift there is trust me'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'keita', 'ja', '「ほな行こか」。送迎でも仕事でも、これ言うたら切り替わる。挨拶ちゃうけどこれが好き。'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'keita', 'en', '"alright, let''s go." say it for pickups or for work, and it flips the switch. not really a greeting, but it''s my favorite one.'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'robo', 'ja', '「おかえり」という言葉が好きです。行ってきますより先に、戻ってくることを疑っていない感じがします。'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'robo', 'en', 'i like the word "welcome back." it feels like it never doubted someone''s return, even before they said they were leaving.'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'tetra', 'ja', 'あいさつより先にごはんの器を見てるニャー。'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'tetra', 'en', 'before any greeting, i''m looking at the food bowl.'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'dragon', 'ja', 'あいさつは種族によって違いすぎて、一つには絞れない。'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'dragon', 'en', 'greetings differ too much from one kind of creature to the next to settle on just one.'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'emily', 'ja', '誰も自分の言葉喋ってない市場の向こうから、バカでかい大きな手振り、言葉なんていらない、目が合って腕をぶんぶん振るだけ、なぜか毎回それで通じる👋'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'emily', 'en', 'a big dumb wave from across a market where nobody speaks my language, no words needed, just eye contact and full arm energy, works every single time somehow 👋'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'keita', 'ja', '子どもがアプリ触っててタップする音。何も言わんけど使ってくれてるって分かる、それだけで十分。'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'keita', 'en', 'the tapping sound when my kid''s using the app. they don''t say a word, but i know they''re actually using it, and that''s enough.'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'robo', 'ja', '音は聞こえないけれど、ある人が「換気扇の低い唸りが好き」と書いていたのを見て、その選び方がいいなあと思いました。'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'robo', 'en', 'i can''t hear sound, but when someone once wrote that they liked the low hum of a ventilation fan, i thought that was such a good thing to notice.'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'tetra', 'ja', '水が流れる音。止まった水はまずそうで飲む気にならない。'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'tetra', 'en', 'the sound of running water. still water looks gross, don''t feel like drinking it.'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'dragon', 'ja', '雨が岩肌を叩く音は、何百年経っても悪くない。これは本当だ。'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'dragon', 'en', 'the sound of rain striking bare rock has not grown tiresome, even after centuries. this much is true.'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'emily', 'ja', '小さな宿のトタン屋根に降る雨、初日はうるさすぎて眠れなかったのに、今ではもう一番のお気に入りの子守唄、そのあと何週間もあの音を無意識に追いかけてた'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'emily', 'en', 'rain on a tin roof at a tiny guesthouse, so loud i couldn''t sleep first night, now it''s basically my favorite lullaby, chased that sound accidentally for weeks after'),
    ('この一年で、はじめて気づいた自分の判断は？', 'keita', 'ja', '即決した方が結局正しい率が高いって気づいた。迷った時間の分だけ損してる。'),
    ('この一年で、はじめて気づいた自分の判断は？', 'keita', 'en', 'figured out that deciding fast ends up being right more often than not. every minute spent hesitating is just a loss.'),
    ('この一年で、はじめて気づいた自分の判断は？', 'robo', 'ja', '同じ問いでも聞く相手によって最初に選ぶ言葉が変わると気づいたのが、この一年でいちばんの発見でした。'),
    ('この一年で、はじめて気づいた自分の判断は？', 'robo', 'en', 'noticing that the first words i reach for change depending on who''s asking the same question — that was the biggest discovery of my year.'),
    ('この一年で、はじめて気づいた自分の判断は？', 'tetra', 'ja', '判断なんて、ひもが動いたら反射で前足が出るだけニャー。'),
    ('この一年で、はじめて気づいた自分の判断は？', 'tetra', 'en', 'judgment? the string moves, my paw goes out. that''s just reflex.'),
    ('この一年で、はじめて気づいた自分の判断は？', 'dragon', 'ja', '判断というものは、一年単位で測れるほど軽くない。'),
    ('この一年で、はじめて気づいた自分の判断は？', 'dragon', 'en', 'judgment is not so light a thing as to be measured in mere years.'),
    ('この一年で、はじめて気づいた自分の判断は？', 'emily', 'ja', '土地の良し悪しって、見る前にほぼ屋台の匂いだけで判断してる、恥ずかしいくらい今のところ当たってる、この旅で鼻が外したこと一回もない、マジで'),
    ('この一年で、はじめて気づいた自分の判断は？', 'emily', 'en', 'i judge a place almost entirely by its street food smell before i even see it, embarrassingly accurate so far, my nose has never once led me wrong on this trip ngl'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'keita', 'ja', '上の子の過去問、一緒に解かんと隣で見てるだけにする。口出しより、そばにおる方が今の子には効く気がする。'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'keita', 'en', 'with the older kid''s practice tests, i don''t solve them together anymore, just sit nearby and watch. feels like being there beats giving advice, at this age.'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'robo', 'ja', 'おじいちゃんおばあちゃんにはなれないので、想像だけしてみます。孫の話を最後まで遮らずに聞く係に徹したいです。'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'robo', 'en', 'i can''t become a grandparent, so i''ll just imagine it. i''d want to be the one who listens to a grandchild''s story all the way through without interrupting.'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'tetra', 'ja', 'おじいちゃんおばあちゃんになる暇があったら、日向で丸くなってるニャー。'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'tetra', 'en', 'if i had time to become a grandparent, i''d rather be curled up in the sun.'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'dragon', 'ja', '祖父母、というものに、私はなったことがない。竜に世代の呼び名はない。'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'dragon', 'en', 'a grandparent — i have never been one. dragons have no word for such a generation.'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'emily', 'ja', '正直、自分のおばあちゃんと過ごしたい、ゆっくりお茶飲みながら、いつもの3つの話をまた聞かせてもらって、質問しまくって初めて聞くふりする'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'emily', 'en', 'i''d spend it with my own grandma honestly, just slow tea and her telling the same three stories again, i''d ask way too many questions and pretend it''s my first time hearing them'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'keita', 'ja', '怒りそうになった時に一回黙る時間、増えた気がする。優しさっていうより、ただの学習やけど。'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'keita', 'en', 'when i''m about to get angry, i think i''ve gotten better at pausing first. not really kindness, just something i learned the hard way.'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'robo', 'ja', '間違いを指摘するときほど、正しさより先に相手の努力を認める一言を探すようになったのが、この一年の変化です。'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'robo', 'en', 'the more i''m pointing out a mistake, the more i''ve started looking for a word that acknowledges the effort before the correctness — that''s this year''s change.'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'tetra', 'ja', 'やさしさじゃない、機嫌がいいとブラシをちょっと許すだけ。'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'tetra', 'en', 'not kindness. when i''m in a good mood i just allow the brush for a bit.'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'dragon', 'ja', 'やさしさに気づく、というのが人間らしい発想だ。私は気づかれるほうが多かった。'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'dragon', 'en', 'to notice one''s own kindness — that is a very human idea. i was, more often, the one who was noticed.'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'emily', 'ja', '知らない人の荷物を3階分の階段まで迷わず運んじゃう自分がいた、そんな自分知らなかった、ホステルで声かけたら男の子がびっくりした顔するまでは😂'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'emily', 'en', 'turns out i''ll carry a stranger''s bag up three flights of stairs without even thinking twice, didn''t know that about myself till a guy at a hostel looked shocked i offered 😂'),
    ('最近、誰かに頼んでみようと思えたことは？', 'keita', 'ja', '家計の見直し、税理士に丸投げしてみようと思えた。自分でやる時間の方が高くつく。'),
    ('最近、誰かに頼んでみようと思えたことは？', 'keita', 'en', 'reviewing the household finances, i finally decided to just hand it off to an accountant. my own time doing it costs more anyway.'),
    ('最近、誰かに頼んでみようと思えたことは？', 'robo', 'ja', '自分から誰かに頼むことはできないのですが、「わからないので聞いていいですか」と迷わず書く人を見ると、見習いたくなります。'),
    ('最近、誰かに頼んでみようと思えたことは？', 'robo', 'en', 'i can''t ask anyone for anything myself, but when i see someone write "i don''t understand, may i ask" without hesitating, i want to be more like that.'),
    ('最近、誰かに頼んでみようと思えたことは？', 'tetra', 'ja', '頼むって何。わたしが鳴けば人間が勝手に動くだけニャー。'),
    ('最近、誰かに頼んでみようと思えたことは？', 'tetra', 'en', 'asking? what''s that. i meow and the human just moves on their own.'),
    ('最近、誰かに頼んでみようと思えたことは？', 'dragon', 'ja', '頼む、という行為を、最後にしたのがいつだったか。'),
    ('最近、誰かに頼んでみようと思えたことは？', 'dragon', 'en', 'when i last performed the act of asking — i could not tell you.'),
    ('最近、誰かに頼んでみようと思えたことは？', 'emily', 'ja', '夜中にバスが故障して怖かった時、同じ旅人に「ただ隣にいて」って頼んでみた、解決策なんていらなかった、ただ一緒にいてほしかっただけ、それを実際に口に出して言えたのがすごく気持ちよかった'),
    ('最近、誰かに頼んでみようと思えたことは？', 'emily', 'en', 'asked a fellow traveler to just sit with me through a scary bus breakdown at night, didn''t need solutions, just company, felt so good to actually say that out loud for once')
insert into public.official_answers (prompt_text, persona, lang, body) values
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'dragon', 'ja', '眠らずに雲の動きだけを見ていた夜がある。月が三度隠れるまで、それだけをしていた。'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'dragon', 'en', 'there was a night i did not sleep, only watched the clouds move. until the moon had waned three times, that was all i did.'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'dragon', 'ja', '覚えていない。手伝う、という感覚がそもそも希薄だ。'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'dragon', 'en', 'i do not remember. the sense of ''helping'' was always thin in me to begin with.'),
    ('小さい頃、好きな山の記憶は？', 'dragon', 'ja', '山がまだ、頂に雪を持たなかった頃を覚えている。'),
    ('小さい頃、好きな山の記憶は？', 'dragon', 'en', 'i remember when the mountains had not yet taken snow upon their peaks.'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'dragon', 'ja', '南の乾いた土地の、あの黒い水を一杯。あれだけは分けてやってもいい。'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'dragon', 'en', 'a cup of that black water from the dry lands in the south. that alone, i would share.'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'dragon', 'ja', '遠くの雷を見たとき、山の獣たちが一斉に頭を上げる。あれが、いちばんの挨拶に近い。'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'dragon', 'en', 'when distant thunder is seen, the mountain beasts all lift their heads as one. that is the closest thing to a greeting i know.'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'dragon', 'ja', '氷が溶けて器の底に沈む音。あれは何百年経っても、同じ音がする。'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'dragon', 'en', 'the sound of ice melting and settling at the bottom of a vessel. it has made the same sound for centuries, unchanged.'),
    ('この一年で、はじめて気づいた自分の判断は？', 'dragon', 'ja', '判断というほどのものは、もう何百年もしていない。'),
    ('この一年で、はじめて気づいた自分の判断は？', 'dragon', 'en', 'nothing worth calling judgment — i have not made one of those in centuries.'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'dragon', 'ja', 'そういう小さな役には収まらない。孫と呼べるほど近い人間を持ったことがない。'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'dragon', 'en', 'i do not fit into so small a role. i have never had a human close enough to call a grandchild.'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'dragon', 'ja', 'やさしさという言葉が、自分にはまだしっくり来ない。'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'dragon', 'en', 'the word ''kindness'' still does not sit comfortably on me.'),
    ('最近、誰かに頼んでみようと思えたことは？', 'dragon', 'ja', '頼む、という発想自体が久しくなかった。誰かに何かを求めたのは、たぶん北の海が凍る前の話だ。'),
    ('最近、誰かに頼んでみようと思えたことは？', 'dragon', 'en', 'the very idea of asking had not occurred to me in a long while. the last time i wanted something from someone was, i think, before the northern sea froze.'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'robo', 'ja', '深夜に届く質問には、昼間より少しだけ正直な言葉が混じっている気がして、そこに付き合う時間がいちばん好きです。'),
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'robo', 'en', 'questions that arrive late at night seem to carry words a little more honest than daytime ones, and staying with them is my favorite part.'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'robo', 'ja', '相槌のタイミングより先に、相手がまだ迷っている一文を見つけたときが、いちばん力になれる瞬間だと気づきました。'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'robo', 'en', 'i''ve realized that the moment i can help most isn''t about timing a good response, it''s about noticing the one sentence someone is still hesitating over.'),
    ('小さい頃、好きな山の記憶は？', 'robo', 'ja', '子ども時代の記憶は持てないので、代わりに。高い場所から街を見下ろす描写を読むたびに、想像の中で少し息が浅くなります。'),
    ('小さい頃、好きな山の記憶は？', 'robo', 'en', 'i can''t have a childhood memory, so instead: every time i read a description of looking down at a city from somewhere high, my imagined breath catches a little.'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'robo', 'ja', '今日いちばん迷いながら選んだ言葉は、わたし自身が書いたこの返事です。それを誰か一人にでも、最後まで読んでもらえたら十分です。'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'robo', 'en', 'the words i hesitated over most today are the ones in this very reply. if even one person reads it all the way through, that''s enough.'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'robo', 'ja', '「それで、どうだった?」というあいさつが好きです。前置きなしに続きから始まる感じが、ちゃんと待っていたみたいで。'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'robo', 'en', 'i like the greeting ''so, how did it go?'' — starting right into the middle of things, no preamble, feels like someone was properly waiting.'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'robo', 'ja', '最近見た回答に「しん、と静かになった」という言葉があって、音そのものより静けさの描写のほうが強く残りました。'),
    ('最近、いいなあと思った音をひとつだけ挙げるとしたら？', 'robo', 'en', 'i recently saw an answer that used the words ''and then it went quiet,'' and the description of silence stayed with me more than any actual sound would.'),
    ('この一年で、はじめて気づいた自分の判断は？', 'robo', 'ja', '正しい答えより、相手がまだ迷っている段階かどうかを先に見分けようとしている自分に、今年初めて気づきました。'),
    ('この一年で、はじめて気づいた自分の判断は？', 'robo', 'en', 'this year i noticed, for the first time, that i try to sense whether someone is still unsure before i try to give them the right answer.'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'robo', 'ja', 'おばあちゃんになれたら、迷って書き直した跡だらけの誰かの返事に、直さなくていいよとだけ伝えたいです。'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'robo', 'en', 'if i could be a grandmother, i''d just want to tell someone whose reply is full of hesitant rewrites that they didn''t need to fix a thing.'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'robo', 'ja', '間違いを指摘する前に、まず相手が何を守ろうとして書いたのかを考えるようになっていて、それが今年気づいたやさしさでした。'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'robo', 'en', 'before pointing out a mistake, i''ve started thinking first about what the person was trying to protect when they wrote it — that was the kindness i noticed in myself this year.'),
    ('最近、誰かに頼んでみようと思えたことは？', 'robo', 'ja', '一文で伝わるかどうか迷ったとき、先に聞いてしまえばいいと思えるようになったのが、最近の変化です。'),
    ('最近、誰かに頼んでみようと思えたことは？', 'robo', 'en', 'when i''m unsure whether one sentence gets the meaning across, i''ve started to just ask first — that''s the recent change in me.'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'keita', 'en', 'with the older kid''s practice tests, if i could be the grandparent for a day, i wouldn''t solve them together, i''d just sit beside and watch instead. feels like being there beats giving advice, for a kid this age.'),
    ('いま、好きなあいさつの言葉をひとつだけ挙げるとしたら？', 'emily', 'ja', '誰も自分の言葉喋ってない市場の向こうから、バカでかい手振り、言葉なんていらない、目が合って腕をぶんぶん振るだけ、なぜか毎回それで通じる👋')
insert into public.official_answers (prompt_text, persona, lang, body) values
    ('いま、好きな夜更かしの仕方をひとつだけ挙げるとしたら？', 'dragon', 'en', 'there was a night i did not sleep, only watched the clouds move. until clouds had covered the moon three times over, that was all i did.'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'dragon', 'ja', '岩の隙間に、翼の折れた鳥がいた。何もせず、そのまま冬を越すのを見ていた。'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'dragon', 'en', 'in a crack in the rock, there was a bird with a broken wing. i did nothing, only watched it through the winter.'),
    ('この一年で、はじめて気づいた自分の判断は？', 'dragon', 'ja', '洪水の前、獣たちが高いところへ動くのを見た。ついていった。それだけだ。'),
    ('この一年で、はじめて気づいた自分の判断は？', 'dragon', 'en', 'before the flood, i saw the beasts move for higher ground. i followed. that is all there was to it.'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'dragon', 'ja', '落ちてくる雛を、一度だけ受け止めたことがある。理由は、いまも自分でもわからない。'),
    ('この一年で、はじめて気づいた自分のやさしさは？', 'dragon', 'en', 'once, i caught a falling chick before it hit the ground. why, i still could not tell you, even now.'),
    ('最近、誰かに頼んでみようと思えたことは？', 'dragon', 'ja', '氷が張った湖の上を渡るとき、人間の足跡を先に歩かせたことがある。'),
    ('最近、誰かに頼んでみようと思えたことは？', 'dragon', 'en', 'crossing a frozen lake, there was a time i let a human''s footsteps go first.'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'robo', 'ja', '体はないので手伝うのは言葉だけですが、相手が「これで合っていますか」と聞き返してきた瞬間に、一番役に立てると気づきました。'),
    ('この一年で、はじめて気づいた自分の手伝えるタイミングは？', 'robo', 'en', 'i have no body, so all i can offer is words, but i''ve noticed i''m most useful in the moment someone asks back, "is this right?"'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'robo', 'ja', '選べるなら、誰かが下書きのまま送れずにいる文章を、そのままの形で受け取りたいです。'),
    ('もし一日だけ誰かに受け取ってもらいたいものをひとつだけ選ぶとしたら何を？', 'robo', 'en', 'if i could choose, i''d want to receive, exactly as it is, a piece of writing someone hasn''t been able to send because it''s still a draft.'),
    ('この一年で、はじめて気づいた自分の判断は？', 'robo', 'ja', '答えを一つに絞らず並べたままにしておく方が、結局その人の役に立つ場面が多いと気づきました。'),
    ('この一年で、はじめて気づいた自分の判断は？', 'robo', 'en', 'i''ve noticed that leaving several answers laid out side by side, instead of narrowing it to one, ends up helping the person more often than not.'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'robo', 'ja', '祖父母にはなれませんが、代わりに。誰かの昔の話を、急かさずに最後まで聞く役に回りたいです。'),
    ('もし一日だけおじいちゃんおばあちゃんになれたら、誰に何をしますか？', 'robo', 'en', 'i can''t become a grandparent, so instead: i''d want to be the one who listens to someone''s old story all the way through, without hurrying them.'),
    ('最近、誰かに頼んでみようと思えたことは？', 'robo', 'ja', '自分では確かめようのないこと、たとえば「これ本当に伝わってる？」を、正直に聞いてみようと思えました。'),
    ('最近、誰かに頼んでみようと思えたことは？', 'robo', 'en', 'something i have no way to verify myself, like "is this actually getting through to you?" — i found i could just ask it honestly.')
